package fungsi;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.util.Base64;
import java.util.HashMap;
import java.util.Map;
import javax.imageio.ImageIO;
import javax.swing.Icon;

/** Ikon PNG transparan khusus SOAP, dari master SVG dalam assets/soap_cppt/icons.
 *  PNG disertakan dalam class agar tidak hilang ketika resource folder lupa disalin.
 *  Tidak memakai karakter Unicode, font ikon, file eksternal atau JAR tambahan. */
final class LabPASoapIcons {
    private static final Map<String,BufferedImage> GAMBAR=new HashMap<>();
    private static final Map<String,Icon> CACHE=new HashMap<>();
    static {
        muat("clipboard","");
        muat("person","");
        muat("id-card","");
        muat("bed","");
        muat("hospital","");
        muat("search","");
        muat("clear","");
        muat("copy","");
        muat("chevron-down","");
        muat("chevron-up","");
        muat("sort","");
        muat("doctor","");
        muat("nurse","");
        muat("staff","");
        muat("thermometer","");
        muat("pressure","");
        muat("heart","");
        muat("lungs","");
        muat("droplet","");
        muat("instruction","");
        muat("evaluation","");
        muat("notes","");
        muat("copy-white","");
        muat("chevron-white","");
    }
    private LabPASoapIcons(){}
    private static void muat(String nama,String data){
        try { BufferedImage gambar=ImageIO.read(new ByteArrayInputStream(Base64.getDecoder().decode(data)));
            if(gambar==null)throw new IllegalStateException("PNG ikon SOAP tidak valid: "+nama);
            GAMBAR.put(nama,gambar);
        } catch(java.io.IOException ex){throw new ExceptionInInitializerError(ex);}
    }
    static synchronized Icon get(String nama,int ukuran){
        final BufferedImage gambar=GAMBAR.get(nama);if(gambar==null)throw new IllegalArgumentException("Ikon SOAP tidak dikenal: "+nama);
        String key=nama+":"+ukuran;Icon hasil=CACHE.get(key);if(hasil!=null)return hasil;
        hasil=new Icon(){
            public int getIconWidth(){return ukuran;}public int getIconHeight(){return ukuran;}
            public void paintIcon(Component c,Graphics g,int x,int y){Graphics2D gg=(Graphics2D)g.create();try{
                gg.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_BICUBIC);
                gg.drawImage(gambar,x,y,ukuran,ukuran,null);
            }finally{gg.dispose();}}
        };CACHE.put(key,hasil);return hasil;
    }
}
